// Automatisiert aus den Erlaeuterungstexten der aktuell gueltigen
// Begutachtungsrichtlinie (2026_10_01_BRi_Pflege.pdf, S. 55-96,
// "5.9 Pflegefachliche Konkretisierung der Module und der Abstufungen
// der Selbstaendigkeit") extrahiert: Definition je Kriterium sowie, wo
// vorhanden, konkrete Abgrenzungsbeispiele pro Selbstaendigkeits-/
// Haeufigkeitsstufe. Dient als Hilfetext im Wizard, damit Nutzer:innen
// dieselben Maszstaebe anlegen wie ein Gutachter.

export interface QuestionExplanation {
  definition?: string;
  /** Index-aligned mit der jeweiligen 4er-Skala (0-3), falls vorhanden. */
  levels?: (string | null)[];
}

export const QUESTION_EXPLANATIONS: Record<string, QuestionExplanation> = {
  "4.1.1": { definition: "Einnehmen von verschiedenen Positionen im Bett, Drehen um die Längsachse, Aufrichten aus dem Liegen Hilfen beim Aufstehen oder Zubettgehen sind unter F 4.6.2 „Ruhen und Schlafen“ zu berücksichtigen.", levels: ["Selbständig ist auch eine Person, die ihre Position unter Nutzung von Hilfsmitteln (Aufrichthilfe, Bettseitenteil, Strickleiter, elektrisch verstellbares Bett) allein verändern kann.", "Die Person kann beispielsweise nach Anreichen eines Hilfsmittels oder Reichen der Hand ihre Lage im Bett verändern.", "Die Person kann beim Positionswechsel nur wenig mithelfen,zum Beispiel auf den Rücken rollen, am Bettgestell festhalten, oder zum Lagern die Arme vor der Brust verschränken und den Kopf auf die Brust legen.", "Die Person kann sich beim Positionswechsel nicht oder nur minimal beteiligen."] },
  "4.1.2": { definition: "Sich auf einem Bett, Stuhl oder Sessel aufrecht halten", levels: ["Selbständig ist eine Person auch dann, wenn sie beim Sitzen gelegentlich ihre Sitzposition korrigieren muss.", "Die Person kann sich nur kurz, zum Beispiel für die Dauer einer Mahlzeit oder eines Waschvorgangs selbständig in der Sitzposition halten, darüber hinaus benötigt sie aber personelle Unterstützung zur Positionskorrektur.", "Die Person kann sich wegen eingeschränkter Rumpfkontrolle auch mit Rückenund Seitenstütze nicht in aufrechter Position halten und benötigt auch während der Dauer einer Mahlzeit oder eines Waschvorgangs personelle Unterstützung zur Positionskorrektur.", "Die Person kann sich nicht in Sitzposition halten. Bei fehlender Rumpf- und Kopfkontrolle kann die Person nur im Bett oder Lagerungsstuhl liegend gelagert werden."] },
  "4.1.3": { definition: "Von einer üblich hohen Sitzgelegenheit aufstehen und sich auf eine andere umsetzen (übliche Sitzhöhe etwa 45 cm)", levels: ["Selbständig ist jemand auch dann, wenn er keine Personenhilfe benötigt, aber ein Hilfsmittel oder einen anderen Gegenstand zum Festhalten oder Hochziehen (zum Beispiel Griffstangen) benutzt oder sich auf Tisch, Armlehnen oder sons tigen Gegenständen abstützen muss, um aufzustehen. Als selbständig ist auch zu bewerten, wer zwar nicht stehen kann, aber sich mit Armkraft ohne personelle Hilfe umsetzen kann (zum Beispiel Rollstuhl – Toilette).", "Die Person kann aus eigener Kraft aufstehen oder sich umsetzen, wenn sie eine Hand oder einen Arm gereicht bekommt.", "Die Pflegeperson muss beim Aufstehen, Umsetzen (erheblichen) Kraftaufwand aufbringen (hochziehen, halten, stützen, heben). Die beeinträchtigte Person hilft jedoch in geringem Maße mit, kann zum Beispiel kurzzeitig stehen.", "Die Person muss gehoben oder getragen werden, Mithilfe ist nicht möglich."] },
  "4.1.4": { definition: "Sich innerhalb einer Wohnung oder im Wohnbereich einer Einrichtung zwischen den Zimmern sicher bewegen Als Anhaltsgröße für übliche Gehstrecken innerhalb einer Wohnung werden mindestens acht Meter festgelegt. Die Fähigkeiten zur örtlichen Orientierung und zum Treppensteigen sind unter Ziffer F 4.2.2 beziehungsweise Ziffer F 4.1.5 zu berücksichtigen.", levels: ["Die Person kann sich ohne Hilfe durch andere Personen fortbewegen. Dies kann gegebenenfalls unter Nutzung von Hilfsmitteln, zum Beispiel Rollator, Rollstuhl oder sonstigen Gegenständen, zum Beispiel Stock oder Möbelstück, geschehen.", "Die Person kann die Aktivität überwiegend selbständig durchführen. Personelle Hilfe ist beispielsweise erforderlich im Sinne von Bereitstellen von Hilfsmitteln (zum Beispiel Rollator oder Gehstock), punktuellem Stützen/Unterhaken oder Beobachtung (Anwesenheit aus Sicherheitsgründen).", "Die Person kann nur wenige Schritte gehen oder sich mit dem Rollstuhl nur wenige Meter fortbewegen oder kann nur mit Stützung oder Festhalten einer Pflegeperson gehen. Auch wenn sich die Person darüber hinaus aus eigenem Willen in ihrer Wohnung krabbelnd oder robbend fortbewegen kann, ändert dies nichts an der Bewertung als „überwiegend unselbständig“.", "Die Person muss getragen oder vollständig im Rollstuhl geschoben werden."] },
  "4.1.5": { definition: "Überwinden von Treppen zwischen zwei Etagen in aufrechter Position", levels: ["Die Person kann ohne Hilfe durch andere Personen in aufrechter Position eine Treppe steigen.", "Die Person kann eine Treppe alleine steigen, benötigt aber Begleitung wegen eines Sturzrisikos (Anwesenheit aus Sicherheitsgründen).", "Treppensteigen ist nur mit Stützen oder Festhalten der Person möglich.", "Person muss getragen oder mit Hilfsmitteln transportiert werden, keine Eigenbeteiligung."] },
  "4.2.1": { definition: "Fähigkeit, Personen aus dem näheren Umfeld wiederzuerkennen, das heißt Menschen, zu denen im Alltag regelmäßig ein direkter Kontakt besteht Dazu gehören zum Beispiel Familienmitglieder, Nachbarn, aber auch Pflegekräfte eines ambulanten Dienstes oder einer stationären Pflegeeinrichtung.", levels: ["Die Person erkennt andere Personen aus ihrem näheren Umfeld unmittelbar.", "Die Person erkennt bekannte Personen beispielsweise erst nach einer längeren Zeit des Kontaktes in einem Gespräch oder sie hat Schwierigkeiten, wenn auch nicht täglich, aber doch in regelmäßigen Abständen, vertraute Personen zu erkennen.", "Die aus dem näheren Umfeld stammenden Personen werden nur selten erkannt oder die Fähigkeit hängt gegebenenfalls von der Tagesform ab, das heißt die Fähigkeit unterliegt im Zeitverlauf erheblichen Schwankungen.", "Auch Familienmitglieder werden nicht oder nur ausnahmsweise erkannt."] },
  "4.2.2": { definition: "Fähigkeit, sich in der räumlichen Umgebung zurechtzufinden, andere Orte gezielt anzusteuern und zu wissen, wo man sich befindet", levels: ["Die Person weiß, in welcher Stadt, auf welchem Stockwerk und gegebenenfalls in welcher Einrichtung sie sich befindet. Sie kennt sich in den regelmäßig genutzten Räumlichkeiten aus. Ein Verirren in den Räumlichkeiten der eigenen Wohnung oder unmittelbar im Wohnbereich einer Einrichtung kommt nicht vor und die Person findet sich auch in der näheren außerhäuslichen Umgebung zurecht. Sie weiß beispielsweise, wie sie zu benachbarten Geschäften, zu einer Bushaltestelle oder zu einer anderen nahe gelegenen Örtlichkeit gelangt.", "Es bestehen Schwierigkeiten, sich in der außerhäuslichen Umgebung zu orientieren, beispielsweise nach Verlassen des Hauses wieder den Weg zurückzufinden. In den eigenen Wohnräumen existieren solche Schwierigkeiten hingegen nicht.", "Die Person hat auch in einer gewohnten Wohnumgebung Schwierigkeiten, sich zurechtzufinden. Regelmäßig genutzte Räumlichkeiten und Wege in der Wohnumgebung werden nicht immer erkannt.", "Selbst in der eigenen Wohnumgebung ist die Person regelmäßig auf Unterstützung angewiesen, um sich zurechtzufinden."] },
  "4.2.3": { definition: "Fähigkeit, zeitliche Strukturen zu erkennen Dazu gehören Uhrzeit, Tagesabschnitte (Vormittag, Nachmittag, Abend et cetera), Jahreszeiten und die zeitliche Abfolge des eigenen Lebens. Aufschluss über die Fähigkeit zur zeitlichen Orientierung geben Antworten auf die Frage nach der Jahreszeit, dem Jahr, dem Wochentag, dem Monat oder der Tageszeit.", levels: ["Die zeitliche Orientierung ist ohne nennenswerte Beeinträchtigungen vorhanden.", "Die Person ist die meiste Zeit über zeitlich orientiert, aber nicht durchgängig. Sie hat zum Beispiel Schwierigkeiten, ohne äußere Orientierungshilfen (Uhr, Dunkelheit et cetera) den Tagesabschnitt zu bestimmen.", "Die zeitliche Orientierung ist die meiste Zeit nur in Ansätzen vorhanden. Die Person ist auch unter Nutzung äußerer Orientierungshilfen zumeist nicht in der Lage, Tageszeiten zu erkennen, zu denen regelmäßig bestimmte Ereignisse stattfinden (zum Beispiel Mittagessen).", "Das Verständnis für zeitliche Strukturen und Abläufe ist kaum oder nicht vor handen."] },
  "4.2.4": { definition: "Fähigkeit, sich an kurz und auch länger zurückliegende Ereignisse oder Beobachtungen zu erinnern Dazu gehört, dass die Person zum Beispiel weiß, was sie zum Frühstück gegessen hat oder mit welchen Tätigkeiten sie den Vormittag verbracht hat. Im Hinblick auf das Langzeitgedächtnis geht es bei Erwachsenen zum Beispiel um die Kenntnis des Geburtsjahres, des Geburtsorts oder wichtiger Bestandteile des Lebensverlaufs wie Eheschließung und Berufstätigkeit.", levels: ["Die Person kann über kurz zurückliegende Ereignisse Auskunft geben oder durch Handlungen und Gesten signalisieren, dass sie sich erinnert.", "Die Person hat Schwierigkeiten, sich an manche kurz zurückliegende Ereignisse zu erinnern, oder muss hierzu länger nachdenken, sie hat aber keine nennenswerten Probleme, sich an Ereignisse aus der eigenen Lebensgeschichte zu erinnern.", "Die Person vergisst kurz zurückliegende Ereignisse häufig. Nicht alle, aber wichtige Ereignisse aus der eigenen Lebensgeschichte sind (noch) präsent.", "Die Person ist nicht (oder nur selten) in der Lage, sich an Ereignisse, Dinge oder Personen aus der eigenen Lebensgeschichte zu erinnern."] },
  "4.2.5": { definition: "Fähigkeit, zielgerichtete Handlungen des Lebensalltags, die eine Abfolge von Teilschritten umfassen, zu steuern Die Betonung liegt in diesem Fall auf dem Begriff Alltagshandlungen. Gemeint sind zielgerichtete Handlungen, die diese Person täglich oder nahezu täglich im Lebensalltag durchführt oder durchgeführt hat, wie zum Beispiel das komplette Ankleiden, Kaffeekochen oder Tischdecken.", levels: ["Die Person ist in der Lage, die erforderlichen Handlungsschritte selbständig in der richtigen Reihenfolge auszuführen oder zu steuern, so dass das angestrebte Ergebnis der Handlung erreicht wird.", "Die Person verliert manchmal den Faden und vergisst, welcher Handlungsschritt der nächste ist. Erhält sie dabei eine Erinnerungshilfe, kann sie die Handlung aber selbständig fortsetzen.", "Die Person hat erhebliche Schwierigkeiten. Sie verwechselt regelmäßig die Reihenfolge der einzelnen Handlungsschritte oder vergisst einzelne, notwendige Handlungsschritte.", "Mehrschrittige Alltagshandlungen werden erst gar nicht begonnen oder nach den ersten Versuchen aufgegeben."] },
  "4.2.6": { definition: "Fähigkeit, folgerichtige und geeignete Entscheidungen im Alltag zu treffen Dazu gehört zum Beispiel die dem Wetter angepasste Auswahl von Kleidung, die Entscheidung über die Durchführung von Aktivitäten wie Einkaufen, Familien angehörige oder Freunde anrufen, einer Freizeitbeschäftigung nachgehen. Zu klären ist hier die Frage, ob die Entscheidungen folgerichtig sind, das heißt geeignet sind, das angestrebte Ziel zu erreichen oder ein gewisses Maß an Sicherheit und Wohlbefinden oder Bedürfnisbefriedigung zu gewährleisten, zum Beispiel warme Kleidung.", levels: ["Die Person kann auch in unbekannten Situationen folgerichtige Entscheidungen treffen, beispielsweise beim Umgang mit unbekannten Personen, die an der Haustür klingeln.", "Im Rahmen der Alltagsroutinen oder in zuvor besprochenen Situationen können Entscheidungen getroffen werden, die Person hat aber Schwierigkeiten in unbekannten Situationen.", "Die Person trifft zwar Entscheidungen, diese Entscheidungen sind jedoch in der Regel nicht geeignet, ein bestimmtes Ziel zu erreichen. Dies ist beispielsweise der Fall, wenn die Person mit nur leichter Bekleidung bei winterlichen Tempe raturen im Freien spazieren gehen will. Weiterhin liegt eine schwere Beeinträchtigung vor, wenn die Person nur mit Unterstützung in Form von Anleitung, Aufforderung, Aufzeigen von Handlungsalternativen in der Lage ist, Entscheidungen zu treffen.", "Die Person kann Entscheidungen auch mit Unterstützung nicht mehr oder nur selten treffen. Sie zeigt keine deutbare Reaktion auf das Angebot mehrerer Entscheidungsalternativen."] },
  "4.2.7": { definition: "Fähigkeit, Sachverhalte zu verstehen und Informationen inhaltlich einordnen zu können Hier geht es um Ereignisse und Inhalte, die Bestandteil des Alltagslebens der meisten Menschen sind. Gemeint ist etwa die Fähigkeit, zu erkennen, dass man sich in einer bestimmten Situation befindet, zum Beispiel gemeinschaftliche Aktivitäten mit anderen Menschen, Versorgung durch eine Pflegekraft, sowie die Fähigkeit, Informationen zum Tagesgeschehen aus den Medien, zum Beispiel Fernsehgerät, Tageszeitung, aufzunehmen und inhaltlich zu verstehen. Gleiches gilt für mündlich von anderen Personen übermittelte Informationen.", levels: ["Die Person kann Sachverhalte und Informationen aus dem Alltagsleben ohne nennenswerte Probleme verstehen.", "Die Person kann einfache Sachverhalte und Informationen nachvollziehen, hat bei komplizierteren jedoch Schwierigkeiten.", "Die Person kann auch einfache Informationen häufig nur nachvollziehen, wenn sie wiederholt erklärt werden. Eine schwere Beeinträchtigung liegt auch dann vor, wenn das Verständnis sehr stark von der Tagesform abhängt.", "Die Person gibt weder verbal noch nonverbal zu erkennen, dass sie Situationen und übermittelte Informationen verstehen kann."] },
  "4.2.8": { definition: "Fähigkeit, Risiken und Gefahren zu erkennen Dazu gehören Gefahren des Alltagslebens wie Strom- und Feuerquellen, Barrieren und Hindernisse auf dem Fußboden beziehungsweise auf Fußwegen, eine problematische Beschaffenheit des Bodens (zum Beispiel Glätte) oder Gefahrenzonen in der außerhäuslichen Umgebung (zum Beispiel verkehrsreiche Straßen, Baustellen).", levels: ["Die Person kann solche Risiken und Gefahrenquellen im Alltagsleben ohne weiteres erkennen, auch wenn sie ihnen aus anderen Gründen (zum Beispiel aufgrund von somatischen Beeinträchtigungen) nicht aus dem Weg gehen kann.", "Die Person erkennt meist nur solche Risiken und Gefahren, die sich in der ver trauten innerhäuslichen Wohn umgebung wiederfinden. Es bestehen aber bei spielsweise Schwierigkeiten, Risiken im Straßenverkehr an ge messen einzuschätzen oder Gefährdungen in ungewohnter Umgebung zu erkennen.", "Die Person kann auch Risiken und Gefahren, denen sie häufig auch in der Wohnumgebung begegnet, oft nicht als solche erkennen.", "Die Person kann Risiken und Gefahren so gut wie gar nicht erkennen."] },
  "4.2.9": { definition: "Fähigkeit, elementare Bedürfnisse verbal oder nonverbal mitzuteilen Das beinhaltet, sich bei stark belastenden Empfindungen in Bezug auf elementare Bedürfnisse wie Schmerzen, Frieren, Hunger oder Durst bemerkbar zu machen. Bei Sprachstörungen kann dies gegebenenfalls durch Laute, Mimik oder Gestik beziehungsweise unter Nutzung von Hilfsmitteln erfolgen. Liegt eine unzureichende Flüssigkeitsaufnahme aufgrund eines nicht ausreichenden Durstgefühls vor, so wird dies im Kriterium \"Trinken\", Ziffer F 4.4.9 bewertet.", levels: ["Die Person kann elementare Bedürfnisse benennen oder durch Laute, Gestik, Mimik oder Nutzung von Hilfsmitteln deutlich machen, um welches Bedürfnis es sich handelt.", "Die Person äußert elementare Bedürfnisse nicht immer von sich aus oder nicht immer eindeutig, kann diese aber auf Nachfrage deutlich machen.", "Es ist nur aus nicht eindeutigem Verhalten (zum Beispiel Mimik, Gestik, Lautgebung, sprachliche Äußerungen) ableitbar, dass elementare Bedürfnisse beste hen. Welches elementare Bedürfnis betroffen ist, kann nicht kommuniziert werden, sondern muss von der Pflegeperson aufwendig eruiert werden. Die Person hat häufig Schwierigkeiten, Zustimmung oder Ablehnung zu signalisieren.", "Die Person äußert nicht oder nur sehr selten Bedürfnisse, auch nicht in nonverbaler Form. Sie kann weder Zustimmung noch Ablehnung deutlich machen."] },
  "4.2.10": { definition: "Fähigkeit, Aufforderungen in Hinblick auf alltägliche Grundbedürfnisse zu verstehen Zu den alltäglichen Grundbedürfnissen gehören zum Beispiel Essen, Trinken, sich kleiden, sich beschäftigen.", levels: ["Aufforderungen und Bitten zu alltäglichen Grundbedürfnissen werden ohne weiteres verstanden.", "Einfache Bitten und Aufforderungen, wie zum Beispiel „Setz dich bitte an den Tisch!“, „Zieh dir die Jacke über!“, „Komm zum Essen!“, werden verstanden; Aufforderungen zu komplexeren Handlungen müssen erklärt werden. Gegebenen falls sind zum Beispiel bei Schwerhörigkeit besonders deutliche Ansprache, Wiederholungen, Zeichensprache, Gebärdensprache oder Schrift erforderlich, um Aufforderungen verständlich zu machen.", "Die Person kann Aufforderungen und Bitten meist nicht verstehen, wenn diese nicht wiederholt geäußert und erläutert werden. Das Verständnis ist sehr von der Tagesform abhängig. Sie zeigt aber Zustimmung oder Ablehnung gegenüber nonverbalen Aufforderungen, zum Beispiel bei Berührungen oder Geleiten an den Esstisch.", "Die Person kann Anleitungen und Aufforderungen kaum oder nicht verstehen."] },
  "4.2.11": { definition: "Fähigkeit, in einem Gespräch Gesprächsinhalte aufzunehmen, sinngerecht zu antworten und zur Weiterführung des Gesprächs Inhalte einzubringen", levels: ["Die Person kommt sowohl in Einzel- als auch in Gesprächen kleiner Gruppen gut zurecht. Sie zeigt im Gespräch Eigeninitiative, Interesse und beteiligt sich, wenn vielleicht auch nur auf direkte Ansprache hin. Ihre Äußerungen passen zu den Inhalten des Gesprächs.", "Die Person kommt in Gesprächen mit einer Person gut zurecht, in Gruppen ist sie jedoch meist überfordert und verliert den Faden oder es treten Wortfindungsstörungen auf. Die Person ist darauf angewiesen, dass langsam und besonders deutlich gesprochen wird und immer wieder Worte und Sätze wiederholt werden, damit sie einem Gespräch folgen kann. Hier ist auch die Kommunikation mit Gebärdensprache zu berücksichtigen.", "Die Person kann auch einem Gespräch nur mit einer Person kaum folgen oder sie kann sich nur wenig oder mit einzelnen Worten beteiligen. Die Person zeigt nur wenig Eigeninitiative, reagiert aber auf Ansprache oder Fragen mit wenigen Worten, zum Beispiel mit ja oder nein; die Person beteiligt sich am Gespräch, weicht aber in aller Regel vom Gesprächsinhalt ab (führt mehr ein Selbstge spräch) oder es besteht leichte Ablenkbarkeit durch Umgebungseinflüsse.", "Ein Gespräch mit der Person, das über einfache Mitteilungen hinausgeht, ist auch unter Einsatz nonverbaler Kommunikation kaum oder nicht möglich."] },
  "4.3.1": { definition: "Dieses Kriterium fasst verschiedene Verhaltensweisen zusammen. Dazu gehören vor allem das (scheinbar) ziellose Umhergehen in der Wohnung oder der Ein richtung und der Versuch desorientierter Personen, ohne Begleitung die Woh nung, Einrichtung zu verlassen oder Orte aufzusuchen, die für diese Person unzugänglich sein sollten, zum Beispiel Treppenhaus, Zimmer anderer Bewohner. Ebenso zu berücksichtigen ist allgemeine Rastlosigkeit in Form von ständigem Aufstehen und Hinsetzen oder Hin- und Herrutschen auf dem Sitzplatz oder im und aus dem Bett." },
  "4.3.2": { definition: "Gemeint sind hier nächtliches Umherirren oder nächtliche Unruhephasen bis hin zur Umkehr des Tag-Nacht-Rhythmus im Sinne von aktiv sein in der Nacht und schlafen während des Tages. Zu bewerten ist, wie häufig Anlass für personelle Unterstützung zur Beruhigung und gegebenenfalls wieder ins Bett bringen besteht. Schlafstörungen wie Einschlafschwierigkeiten am Abend oder Wach phasen während der Nacht sind nicht zu werten. Andere nächtliche Hilfen, zum Beispiel Hilfen zur Orientierung, Aufstehen, zu Bett bringen, Hilfe bei nächtli chen Toilettengängen, körperbezogene Pflegemaßnahmen oder Lagerungen sind nur unter F 4.6.2; Ruhen und Schlafen, Medikamentengabe und andere angeordnete Maßnahmen aus dem Modul 5 sind nur dort zu bewerten." },
  "4.3.3": { definition: "Selbstschädigendes und autoaggressives Verhalten kann zum Beispiel darin bestehen, sich selbst durch Gegenstände zu verletzen, ungenießbare Substanzen zu essen und zu trinken, sich selbst zu schlagen und sich selbst mit den Fingernägeln oder Zähnen zu verletzen." },
  "4.3.4": { definition: "Gemeint sind hier aggressive auf Gegenstände gerichtete Handlungen wie Gegenstände wegstoßen oder wegschieben, gegen Gegenstände schlagen, das Zerstören von Dingen sowie das Treten nach Gegenständen." },
  "4.3.5": { definition: "Physisch aggressives Verhalten gegenüber anderen Personen kann zum Beispiel darin bestehen, nach Personen zu schlagen oder zu treten, andere mit Zähnen oder Fingernägeln zu verletzen, andere zu stoßen oder wegzudrängen, oder in Verletzungsversuchen gegenüber anderen Personen mit Gegenständen." },
  "4.3.6": { definition: "Verbale Aggression kann sich zum Beispiel in verbalen Beschimpfungen oder in der Bedrohung anderer Personen ausdrücken." },
  "4.3.7": { definition: "Andere pflegerelevante vokale Auffälligkeiten können sein: Lautes Rufen, Schreien, Klagen ohne nachvollziehbaren Grund, vor sich hin schimpfen, fluchen, seltsame Laute von sich geben, ständiges Wiederholen von Sätzen und Fragen." },
  "4.3.8": { definition: "Hier ist die Abwehr von Unterstützung, zum Beispiel bei der Körperpflege, die Verweigerung der Nahrungsaufnahme, der Medikamenteneinnahme oder anderer notwendiger Verrichtungen sowie die Manipulation an Vorrichtungen wie zum Beispiel an Kathetern, Infusionen oder Sondenernährung gemeint. Dazu gehört nicht die willentliche (selbstbestimmte) Ablehnung bestimmter Maßnahmen." },
  "4.3.9": { definition: "Wahnvorstellungen beziehen sich zum Beispiel auf die Vorstellung, mit Verstorbenen oder imaginären Personen in Kontakt zu stehen, oder auf die Vorstellung, verfolgt, bedroht oder bestohlen zu werden." },
  "4.3.10": { definition: "Es geht hier um ausgeprägte Ängste, die wiederkehrend sind und als bedrohlich erlebt werden. Die Person hat keine eigene Möglichkeit/Strategie zur Bewälti gung und Überwindung der Angst. Die Angst führt zu erheblichen psychischen oder körperlichen Beschwerden, einem hohen Leidensdruck und Beeinträchtigungen in der Bewältigung des Alltags. Ängste lassen sich nicht nur bei Angststörungen finden, sondern auch bei anderen psychischen Störungen wie zum Beispiel bei Schizophrenie und Depression. Darüber hinaus können ausgeprägte Ängste im Sinne dieses Kriteriums auch durch rein somatische Krankheiten wie onkologische Erkrankungen verursacht werden. Das Herstellen einer angstfreien Atmosphäre durch bloße Anwesenheit einer weiteren Person (ohne deren aktive personelle Unterstützung) wird hier nicht bewertet." },
  "4.3.11": { definition: "Antriebsstörungen wie Antriebschwäche, Antriebsmangel oder Antriebsarmut können Vorstufen der Antriebslosigkeit sein. Die Antriebslosigkeit stellt eine sehr schwere Form der Antriebsstörung dar. Die depressive Stimmungslage äußert sich insbesondere durch Hoffnungslosigkeit, Niedergeschlagenheit oder Verzweiflung. Es kann sich aber beispielsweise auch durch ein Gefühl der Gefühllosigkeit mit fehlender emotionaler Schwin gungsfähigkeit zeigen, so dass weder Freude noch Trauer empfunden werden können. Antriebslosigkeit bei depressiver Stimmungslage zeigt sich zum Beispiel daran, dass die Person kaum Interesse an der Umgebung hat, kaum Eigeninitiative aufbringt und eine aufwendige Motivierung durch andere benötigt, um etwas zu tun. Hier ist nicht gemeint, dass Menschen mit rein kognitiven Beeinträchtigungen, zum Beispiel bei Demenz, Impulse benötigen, um eine Handlung zu beginnen oder fortzuführen." },
  "4.3.12": { definition: "Sozial inadäquate Verhaltensweisen sind zum Beispiel distanzloses Verhalten, auffälliges Einfordern von Aufmerksamkeit, sich vor anderen in unpassenden Situationen entkleiden, unangemessenes Greifen nach Personen oder unange messene körperliche oder verbale sexuelle Annäherungsversuche." },
  "4.3.13": { definition: "Sonstige pflegerelevante inadäquate Handlungen sind zum Beispiel Nesteln an der Kleidung, ständiges Wiederholen der gleichen Handlung (Stereotypien), planlose Aktivitäten, Verstecken oder Horten von Gegenständen, Kotschmieren, Urinieren in die Wohnung." },
  "4.4.1": { definition: "Sich die Hände, das Gesicht, die Arme, die Achselhöhlen sowie den vorderen Hals- und Brustbereich waschen und abtrocknen", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn benötigte Gegenstände, zum Beispiel Seife, Waschlappen, bereitgelegt werden oder sie Aufforderung beziehungsweise punktuelle Teilhilfen, zum Beispiel Waschen unter den Achseln oder der Brust, erhält.", "Die Person kann geringe Anteile der Aktivität selbständig durchführen, sich zum Beispiel nur Hände oder Gesicht waschen, oder benötigt umfassende Anleitung.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.2": { definition: "Kämmen, Zahnpflege, Prothesenreinigung, Rasieren", levels: ["Die Person kann die beschriebenen Aktivitäten ohne personell Hilfe durchführen.", "Die Person kann die Aktivitäten selbständig durchführen, wenn benötigte Gegenstände bereitgelegt oder gerichtet werden, zum Beispiel Aufdrehen der Zahn pastatube, Auftragen der Zahnpasta auf die Bürste, Aufbringen von Haftcreme auf die Prothese, Anreichen oder Säubern des Rasierapparates. Alternativ sind Aufforderungen oder punktuelle Teilhilfen erforderlich wie Korrekturen nach dem Kämmen oder nur das Kämmen des Hinterkopfes, das Reinigen der hinteren Backenzähne bei der Zahn-, Mundpflege beziehungsweise die Nachrasur bei sonst selbständigem Rasieren.", "Die Person kann geringe Anteile der Aktivität selbständig leisten, so beginnt sie zum Beispiel mit dem Zähneputzen oder der Rasur, ohne die Aktivität zu Ende zu führen.", "Die Person kann sich an den Aktivitäten nicht oder nur minimal beteiligen."] },
  "4.4.3": { definition: "Den Intimbereich waschen und abtrocknen", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn benötigte Utensilien, zum Beispiel Seife, Waschlappen bereitgelegt werden oder sie Aufforderung beziehungsweise punktuelle Teilhilfen erhält.", "Die Person kann geringe Anteile der Aktivität selbständig durchführen, sich zum Beispiel nur den vorderen Intimbereich waschen.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.4": { definition: "Durchführung des Dusch- und Wannenbades einschließlich des Waschens der Haare Dabei sind neben der Fähigkeit, den Körper waschen zu können, auch Sicher heitsaspekte zu berücksichtigen. (Teil-)Hilfen beim Waschen in der Dusche und Wanne sind hier ebenso zu berücksichtigen wie die Hilfe beim Ein- und Aussteigen oder eine notwendige Überwachung während des Duschens und Badens. Dazu gehört auch das Abtrocknen, Haare waschen und föhnen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn Utensilien vorbereitet beziehungsweise bereitgestellt werden, einzelne Handreichungen geleistet werden, zum Beispiel Stützen beim Ein-, Aussteigen, Bedienung eines Badewannenlifters, Hilfe beim Haarewaschen oder Föhnen, beim Abtrocknen, oder wenn während des Duschens und Badens aus nachvollziehbaren Sicherheits gründen Anwesenheit erforderlich ist.", "Die Person kann geringe Anteile der Aktivität selbständig durchführen, zum Beispiel das Waschen des vorderen Oberkörpers.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.5": { definition: "Bereitliegende Kleidungsstücke, zum Beispiel Unterhemd, T-Shirt, Hemd, Bluse, Pullover, Jacke, BH, Schlafanzugoberteil oder Nachthemd, an- und ausziehen Die Beurteilung ist unabhängig davon vorzunehmen, ob solche Kleidungsstücke derzeit getragen werden. Die situationsgerechte Auswahl der Kleidung ist nicht hier, sondern unter Ziffer F 4.2.6 zu berücksichtigen. Das An- und Ablegen von körpernahen Hilfsmitteln ist unter Ziffer F 4.5.7 zu berücksichtigen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität beispielsweise selbständig durchführen, wenn Kleidungsstücke passend angereicht oder gehalten werden beim Anziehen eines Hemdes et cetera. Auch wenn Hilfe nur bei Verschlüssen erforderlich ist, trifft die Bewertung „überwiegend selbständig“ zu, ebenso wenn nur Kontrolle des Sitzes der Kleidung und Aufforderungen zur Vervollständigung der Handlung erforderlich sind.", "Die Person kann beispielsweise nur die Hände in die Ärmel eines bereitgehaltenen T-Shirts schieben.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "diaet": { definition: "Einhalten einer Diät und anderer krankheits- oder therapiebedingter Verhaltensvorschriften Fähigkeit, die Notwendigkeit einer Diät oder einer ärztlich angeordneten Vorschrift, die sich auf vitale Funktionen bezieht, einzusehen In diesem Kriterium geht es um die Einsichtsfähigkeit der Person zur Einhaltung von ärztlich angeordneten Diäten sowie Vorschriften, die sich auf vitale Funktionen (insbesondere Atmung und Herzkreislauffunktion) beziehen. Es geht nicht um die Vorbereitung oder Durchführung einer Verhaltensvorschrift oder Diät. Ausschlaggebend für eine Wertung ist, ob die Person mental in der Lage ist, die Notwendigkeit zu erkennen und die Verhaltensvorschrift einzuhalten. Zu werten ist, wie häufig aufgrund des Nichtbeachtens ein direktes Eingreifen erforderlich ist, sofern dies nicht in anderen Modulen berücksichtigt wurde. Bei manchen Erkrankungen werden bestimmte Diäten 11 oder Essvorschriften oder andere Verhaltensvorschriften von der Ärztin oder vom Arzt angeordnet. Dazu gehören auch die ärztlich angeordnete Nahrungs- und Flüssigkeitszufuhr, in der sowohl die Art und Menge der Lebensmittel wie auch die Art und der Zeitpunkt der Aufnahme aus therapeutischen Gründen geregelt sind, zum Bei spiel bei Stoffwechselstörungen, Nahrungsmittelallergien, bei Essstörungen wie 11 Eine Diät (Syn.: modifizierte Kostform) ist definiert als angeordnete Nahrungs- und Flüssigkeitszufuhr, in der sowohl die Art und Menge der Lebensmittel wie auch Art und Zeitpunkt der Aufnahme aus therapeutischen Gründen geregelt sind. Eine Diät wird als Teil der Behandlung oder Prävention einer Erkrankung oder klinischen Kondition eingesetzt, um bestimmte Substanzen in Nahrungsmitteln zu eliminieren, zu vermindern oder zu erhöhen. Beispiele für Diäten sind die glutenfreie oder laktosefreie Diät. (Valentini L et al., Leitlinie der Deutschen Gesellschaft für Ernährungsmedizin (DGEM) – DGEM-Terminologie in der Klinischen Ernährung, Aktuell Ernährungsmed 2013; 38: 97–111) Anorexie oder Prader-Willi-Syndrom. Verhaltensvorschriften zur gesunden Lebensführung im Sinne von zum Beispiel einer ausgewogenen Ernährung und einer ausreichenden Flüssigkeitsmenge sowie die Vermeidung von Suchtmitteln sind hier nicht zu berücksichtigen. Andere Verhaltensvorschriften können sich zum Beispiel auf die Sicherstellung einer Langzeit-Sauerstoff-Therapie bei unruhigen Personen beziehen. Diese Vorschriften sind im Einzelnen zu benennen. Im Weiteren sind der Grad der Selbständigkeit bei der Einhaltung dieser Vorschriften und der daraus resultierende Bedarf an personeller Unterstützung zu beurteilen. Nicht gemeint ist die selbstbestimmte Ablehnung von ärztlichen Vorschriften bei erhaltenen mentalen Funktionen. Liegen keine Vorschriften vor, ist das Feld „entfällt, nicht erforderlich“ anzu kreuzen.", levels: ["Die Person kann die Vorschriften selbständig einhalten. Das Bereitstellen einer Diät reicht aus.", "Die Person benötigt Erinnerung, Anleitung. In der Regel reicht das Bereitstellen der Diät nicht aus. Darüberhinausgehendes Eingreifen ist maximal einmal täglich erforderlich.", "Die Person benötigt meistens Anleitung, Beaufsichtigung. Das Bereitstellen der Diät reicht nicht aus. Darüberhinausgehendes Eingreifen ist mehrmals täglich erforderlich.", "Die Person benötigt immer Anleitung, Beaufsichtigung. Das Bereitstellen der Diät reicht nicht aus. Darüberhinausgehendes Eingreifen ist (fast) durchgehend erforderlich."] },
  "4.4.6": { definition: "Bereitliegende Kleidungsstücke, zum Beispiel Unterwäsche, Hose, Rock, Strümpfe und Schuhe, an- und ausziehen Die Beurteilung ist unabhängig davon vorzunehmen, ob solche Kleidungsstücke derzeit getragen werden. Die situationsgerechte Auswahl der Kleidung ist unter Ziffer F 4.2.6 zu berücksichtigen. Das An- und Ablegen von körpernahen Hilfsmitteln ist unter Ziffer F 4.5.7 zu berücksichtigen, zum Beispiel Kompressionsstrümpfe.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn ihr Schuhe beziehungsweise Kleidungsstücke angereicht oder gehalten werden (Einstiegshilfe). Auch wenn Hilfe nur bei Verschlüssen, zum Beispiel Schnürsenkel binden, Knöpfe schließen oder Kontrolle des Sitzes der Kleidung, und Aufforderungen, die Handlung zu beginnen oder zur Vervollständigung der Handlung erforderlich sind, trifft die Bewertung „überwiegend selbständig“ zu.", "Die Person kann die Aktivität zu einem geringen Anteil selbständig durchführen. Beispielsweise gelingt nur das Hochziehen von Hose oder Rock vom Oberschenkel zur Taille selbständig.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.7": { definition: "Zerteilen von Nahrung in mundgerechte Stücke und Eingießen von Getränken Dazu gehört das Zerteilen von belegten Brotscheiben, Obst oder anderen Speisen in mundgerechte Stücke, zum Beispiel das Kleinschneiden von Fleisch, das Zerdrücken von Kartoffeln, Verschlüsse von Getränkeflaschen öffnen, Getränke aus einer Flasche oder Kanne in ein Glas beziehungsweise eine Tasse eingießen, gegebenenfalls unter Nutzung von Hilfsmitteln wie Antirutschbrett oder sonstigen Gegenständen wie Spezialbesteck.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Es ist punktuelle Hilfe erforderlich, zum Beispiel beim Öffnen einer Flasche oder beim Schneiden von harten Nahrungsmitteln.", "Die Person kann die Aktivität zu einem geringen Teil selbständig durchführen, beispielsweise schneidet sie zwar belegte Brotscheiben, schafft es aber nicht, mundgerechte Stücke herzustellen. Die Person kann Getränke nicht eingießen.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.8": { definition: "Bereitgestellte, mundgerecht zubereitete Speisen essen Dies beinhaltet das Aufnehmen, Zum-Mund-Führen, gegebenenfalls Abbeißen, Kauen und Schlucken von mundgerecht zubereiteten Speisen, die üblicherweise mit den Fingern gegessen werden, zum Beispiel Brot, Kekse, Obst oder das Essen mit Gabel oder Löffel, gegebenenfalls mit speziellen Hilfsmitteln wie adaptiertem Besteck. Zu berücksichtigen ist auch, inwieweit die Notwendigkeit der ausreichenden Nahrungsaufnahme (auch ohne Hungergefühl oder Appetit) erkannt und die empfohlene, gewohnte Menge tatsächlich gegessen wird. Das Einhalten von Diäten ist nicht hier, sondern unter Ziffer F 4.5.16 zu bewerten. Die Beurteilung ist auch dann vorzunehmen, wenn die Nahrungsaufnahme über eine Sonde beziehungsweise parenteral erfolgt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann überwiegend selbständig essen, benötigt aber punktuelle Anleitung, muss beispielsweise aufgefordert werden, mit dem Essen zu beginnen oder weiterzuessen. Es sind punktuelle Hilfen erforderlich, zum Beispiel Zurücklegen aus der Hand gerutschter Speisen oder Besteck in die Hand geben.", "Es muss aufwendig zur Nahrungsaufnahme motiviert werden oder die Nahrung muss größtenteils gereicht werden oder es ist ständige und unmittelbare Ein greifbereitschaft der Pflegeperson erforderlich, aufgrund von Aspirationsgefahr.", "Die Nahrung muss (nahezu) komplett gereicht werden. Als unselbständig zu bewerten sind auch Personen, die nicht schlucken können."] },
  "4.4.9": { definition: "Bereitstehende Getränke aufnehmen, gegebenenfalls mit Gegenständen wie Trinkhalm, Spezialbecher mit Trinkaufsatz Zu berücksichtigen ist auch, inwieweit die Notwendigkeit der Flüssigkeitsauf nahme (auch ohne ausreichendes Durstgefühl) erkannt und die empfohlene oder gewohnte Menge tatsächlich getrunken wird. Die Beurteilung der Selbständigkeit ist auch dann vorzunehmen, wenn die Flüssigkeitsaufnahme über eine Sonde beziehungsweise parenteral erfolgt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann selbständig trinken, wenn über das Bereitstellen hinaus ein Glas, eine Tasse unmittelbar in den Aktionsradius der Person positioniert oder sie ans Trinken erinnert wird.", "Das Trinkgefäß muss beispielsweise in die Hand gegeben werden, das Trinken erfolgt jedoch selbständig, oder die Person muss zu fast jedem Schluck motiviert werden oder es ist ständige und unmittelbare Eingreifbereitschaft der Pflege person erforderlich, aufgrund von Aspirationsgefahr.", "Getränke müssen (nahezu) komplett gereicht werden. Als unselbständig zu bewerten sind auch Personen, die nicht schlucken können."] },
  "4.4.10": { definition: "Gehen zur Toilette, Hinsetzen und Aufstehen, Sitzen während der Blasen- oder Darmentleerung, Intimhygiene und Richten der Kleidung Die Beurteilung ist auch dann vorzunehmen, wenn anstelle der Toilettenbenutzung eine Versorgung mit Hilfsmitteln erfolgt, zum Beispiel Inkontinenzmaterial, Katheter, Urostoma, Ileo- oder Colostoma.", levels: ["Die Person kann die Aktivität ohne personelle Hilfe durchführen.", "Die Person kann den größten Anteil der Aktivität selbständig durchführen. Personelle Hilfe kann sich beispielsweise beschränken auf einzelne Handlungs schritte wie: → nur Bereitstellen und Leeren des Toilettenstuhls (alternativ Urinflasche oder anderer Behälter), → nur Aufforderung oder Orientierungshinweise zum Auffinden der Toilette oder Begleitung auf dem Weg zur Toilette, → nur Anreichen von Toilettenpapier oder Waschlappen, Intimhygiene nur nach Stuhlgang, → nur Unterstützung beim Hinsetzen, Aufstehen von der Toilette, → nur punktuelle Hilfe beim Richten der Bekleidung.", "Die Person kann nur einen geringen Anteil der Aktivität selbständig durchführen, zum Beispiel nur Richten der Bekleidung oder Intimhygiene nur nach Wasserlassen.", "Die Person kann sich nicht oder nur minimal an der Aktivität beteiligen."] },
  "4.4.11": { definition: "Inkontinenz- und Stomasysteme sachgerecht verwenden, nach Bedarf wechseln und entsorgen Dazu gehört, Inkontinenzsysteme, zum Beispiel Inkontinenzvorlagen, Inkontinenzhose mit Klebestreifen oder Pants, sachgerecht verwenden, nach Bedarf wechseln und entsorgen. Dazu gehört auch das Entleeren, Wechseln eines Urinbeutels bei Dauerkatheter, Urostoma oder die Anwendung eines Urinalkondoms. Die regelmäßige Einmalkatheterisierung ist nicht hier, sondern unter Ziffer F 4.5.10 zu erfassen.", levels: ["Die Person kann Hilfsmittel selbständig benutzen.", "Die Person kann die Aktivität überwiegend selbständig durchführen, wenn Inkontinenzsysteme angereicht oder entsorgt werden oder die Person an den Wechsel erinnert wird.", "Die Person kann sich am Wechsel der Inkontinenzsysteme beteiligen, zum Beispiel nur Vorlagen einlegen oder Inkontinenzhosen nur entfernen.", "Beteiligung ist nicht oder nur minimal möglich."] },
  "4.4.12": { definition: "Inkontinenz- und Stomasysteme sachgerecht verwenden, nach Bedarf wechseln und entsorgen Dazu gehört, Inkontinenzsysteme, zum Beispiel große Vorlagen mit Netzhose, Inkontinenzhose mit Klebestreifen oder Pants, sachgerecht verwenden, nach Bedarf wechseln und entsorgen. Dazu gehört auch die Anwendung eines Analtampons oder das Entleeren oder Wechseln eines Stomabeutels bei Enterostoma. Die Pflege des Stomas und der Wechsel einer Basisplatte sind unter F 4.5.9 zu berücksichtigen.", levels: ["Die Person kann Hilfsmittel selbständig benutzen.", "Die Person kann die Aktivität überwiegend selbständig durchführen, wenn Inkontinenzsysteme bereitgelegt und entsorgt werden oder die Person an den Wechsel erinnert wird.", "Die Person kann sich am Wechsel der Inkontinenzsysteme beteiligen, zum Beispiel Mithilfe beim Wechsel eines Stomabeutels. Bei Vorliegen einer Stuhlinkontinenz sind Ressourcen beim Wechsel des Inkontinenzmaterials eher selten.", "Beteiligung ist nicht oder nur minimal möglich."] },
  "4.4.13": { definition: "Ernährung über einen parenteralen Zugang (zum Beispiel einen Port) oder über einen Zugang in Magen oder Dünndarm (PEG/PEJ)", levels: ["Die Person führt die Versorgung ohne Fremdhilfe durch. Wenn die Versorgung mit Hilfe erfolgt, werden folgende Ausprägungen unterschieden: Die Person erhält zusätzlich zur oralen Nahrungsaufnahme Nahrung oder Flüssigkeit parenteral oder über Sonde, aber nur gelegentlich oder vorübergehend.", "Die Person erhält in der Regel täglich Nahrung oder Flüssigkeit parenteral oder über Sonde und täglich oral Nahrung. Sie wird zum Teil, aber nicht ausreichend über die orale Nahrungsaufnahme ernährt und benötigt zur Nahrungsergänzung beziehungsweise zur Vermeidung von Mangelernährung täglich Sondenkost oder Flüssigkeit.", "Die Person erhält ausschließlich oder nahezu ausschließlich Nahrung und Flüssigkeit parenteral oder über Sonde. Eine orale Gabe erfolgt nicht oder nur in geringem Maße zur Förderung der Sinneswahrnehmung."] },
  "4.5.1": { definition: "Orale Medikation, Augen-, Ohren- oder Nasentropfen beziehungsweise -spray, Dosieraerosole oder Pulverinhalatoren, Zäpfchen und Medikamentenpflaster Das Ausmaß der Hilfestellung kann von einmal wöchentlichem Stellen der Medikamente im Wochendispenser bis zu mehrfach täglicher Einzelgabe differieren. Werden Medikamente verabreicht, ist das Stellen nicht gesondert zu berücksichtigen. Berücksichtigt wird der einzelne Applikationsort (Augen, Ohren und Nase zählen als jeweils ein Ort) und die Applikationshäufigkeit (unabhängig von der Anzahl der dort applizierten Arzneimittel). Die Applikation von Dosieraerosolen oder Pulverinhalatoren zählt als eine weitere Maßnahme. Unter oraler Medikation wird auch die Medikamentengabe über PEG berücksichtigt. Analog zu Zäpfchen sind auch andere rektal zu verabreichende Medikamente zu bewerten. Abführ methoden sind unter F 4.5.10 „regelmäßige Einmalkatetherisierung und Nutzung von Abführmethoden“ zu bewerten." },
  "4.5.2": { definition: "Subkutane und intramuskuläre Injektionen und subkutane Infusionen Dazu gehören zum Beispiel Insulin-Injektionen oder auch die Versorgung mit Medikamentenpumpen über einen subkutanen Zugang." },
  "4.5.3": { definition: "(zum Beispiel Port) Versorgung und Verbände venöser Zugänge (zum Beispiel Shaldon, Broviac und andere) sowie die Port-Versorgung Hierunter fallen die Versorgung und Verbände venöser Zugänge (zum Beispiel Shaldon, Broviac und andere), auch die Port-Versorgung. Ebenso wird das Einbringen von Medikamenten in einen vorhandenen venösen Zugang berücksichtigt. Das Anhängen von Nährlösungen (gegebenenfalls auch mit Medikamentenzusatz) zur parenteralen Ernährung wird unter der Ziffer F 4.4.13 erfasst. Analog ist auch die Versorgung intrathekaler Zugänge hier zu erfassen." },
  "4.5.4": { definition: "Absaugen, Sauerstoffgabe über Brille oder Maske Absaugen kann zum Beispiel bei beatmeten oder tracheotomierten Patienten in sehr unterschiedlicher und wechselnder Häufigkeit notwendig sein. Es ist der durchschnittliche Bedarf anzugeben. Ebenso ist hier das An- und Ablegen von Sauerstoffbrillen oder analog auch von Atemmasken zur nächtlichen Druckbe atmung zu erfassen sowie das Bereitstellen eines Inhalationsgerätes (inklusive deren Reinigung). Jede Maßnahme ist auch einzeln zu berücksichtigen." },
  "4.5.5": { definition: "Anwendungen von ärztlich angeordneten Salben, Cremes, Emulsionen et cetera, außerdem Kälte- und Wärmeanwendungen Hier sind alle externen Anwendungen mit ärztlich angeordneten Salben, Cremes, Emulsionen et cetera abzubilden, außerdem Kälte- und Wärmeanwendungen, die zum Beispiel bei rheumatischen Erkrankungen angeordnet werden. Einrei bungen gegebenenfalls mit verschiedenen Produkten, Kälte- oder Wärmeanwendungen sind jeweils als eine Maßnahme zu berücksichtigen, unabhängig von der Anzahl der Applikationsorte. Die allgemeine Hautpflege – auch zur Prophylaxe – ist nicht zu berücksichtigen." },
  "4.5.6": { definition: "Ärztlich angeordnete Messungen von Körperzuständen und deren Deutung Die Aktivität umfasst Messungen wie zum Beispiel Blutdruck, Puls, Blutzucker, Temperatur, Körpergewicht, Flüssigkeitshaushalt, soweit diese auf ärztliche Anordnung erfolgen. Dabei geht es nicht nur darum, die Messung durchzuführen, sondern auch notwendige Schlüsse zu ziehen, etwa zur Festlegung der erforderlichen Insulindosis oder zur Notwendigkeit anderer Maßnahmen, wie das Umstellen der Ernährung oder auch das Aufsuchen einer Ärztin oder eines Arztes. Dies gilt beispielsweise auch für Menschen mit erhöhtem Blutdruck, die je nach Blutdruckwerten ihre Medikation anpassen müssen. Eine Routinemessung von Körperzuständen, die nicht gezielt auf eine bestehende Erkrankung ausgerichtet ist, kann nicht bewertet werden." },
  "4.5.7": { definition: "An- oder Ablegen von Prothesen, Orthesen, Epithesen, Sehhilfen, Hörgeräten, kieferorthopädische Apparaturen und Kompressionsstrümpfen für Arme und Beine (inklusive deren Reinigung) Hierunter versteht man ausschließlich das An- oder Ablegen von Prothesen, Orthesen, Epithesen, Sehhilfen, Hörgeräten, kieferorthopädischen Apparaturen und Kompressionsstrümpfen für Arme und Beine (inklusive deren Reinigung). Wenn eine Versorgung mit Kompressionsstrümpfen aus medizinischen Gründen durch eine andere ärztlich verordnete Kompressionsversorgung ersetzt wird, ist dies zu bewerten. Das alleinige Reinigen ist nicht zu berücksichtigen. Das Anund Ablegen paariger Hilfsmittel wird jeweils als eine Maßnahme gezählt. Der Umgang mit Zahnprothesen ist ausschließlich unter der Ziffer F 4.4.2 zu erfassen." },
  "4.5.8": { definition: "Versorgung chronischer Wunden Die Aktivität beinhaltet die Versorgung chronischer Wunden, wie zum Beispiel Ulcus cruris oder Dekubitus. Immer wieder auftretende Wunden (intermittierendes Wundgeschehen), die regelmäßig sowie auf Dauer nach ärztlicher Verord nung versorgt werden müssen, sind als chronische Wunden zu werten." },
  "4.5.9": { definition: "Pflege künstlicher Körperöffnungen Gemeint ist hier die Pflege künstlicher Körperöffnungen wie Tracheostoma, PEG, suprapubischer Blasenkatheter, Urostoma, Colo- oder Ileostoma. Hierbei ist auch das Reinigen des Katheters, die Desinfektion der Einstichstelle der PEG und falls notwendig auch der Verbandswechsel zu bewerten. Die Pflege eines Urostoma, Colo- oder Ileostoma ist in der Regel mit dem Wechsel der Basisplatte oder dem Wechsel eines einteiligen Systems verbunden. Der einfache Wechsel oder das Entleeren eines Stoma- oder Katheterbeutels oder das Anhängen von Sonden nahrung sind unter den Ziffern F 4.4.11 ff. zu werten." },
  "4.5.10": { definition: "Einmalkatheterisierung und Abführmethoden Regelmäßige Einmalkatheterisierungen kommen insbesondere bei neurogenen Blasenentleerungsstörungen vor. Mit Abführmethoden sind Anwendungen von Klistier, Einlauf, digitale Ausräumung gemeint. Die alleinige Gabe von Abführ mitteln (Laxantien) ist unter F 4.5.1 zu berücksichtigen." },
  "4.5.11": { definition: "Eigenübungen aus einer Heilmitteltherapie, aufwendige therapeutische Maßnahmen zur Sekretelimination, Peritonealdialyse Bei vielen Erkrankungen werden aus einer Heilmitteltherapie heraus Anweisungen zu einem häuslichen Eigenübungsprogramm gegeben, welches dauerhaft und regelmäßig durchgeführt werden soll. Hierzu zählen zum Beispiel krankengymnastische Übungen, Atemübungen oder logopädische Übungen sowie die Durchführung spezifischer Therapien nach Bobath oder Vojta. Nicht gemeint sind hier die Therapien im Rahmen der Heilmittelverordnung durch Therapeutinnen oder Therapeuten im Hausbesuch sowie deren Unterstützung. Des Weiteren sind aufwendige therapeutische Maßnahmen zur Sekretelimination (ausgenommen Absaugen), und die Durchführung ambulanter Peritonealdialyse (CAPD) zu nennen. Prophylaktische Maßnahmen und aktivierende Pflege werden hier nicht berücksichtigt." },
  "4.5.12": { definition: "Therapiemaßnahmen, die sowohl zeit- als auch technikintensiv durch geschulte Pflegepersonen durchgeführt werden Gemeint sind hier spezielle Therapiemaßnahmen wie Hämodialyse oder Beat mung, die im häuslichen Umfeld durchgeführt werden können, wenn ständige Überwachung während der Maßnahme durch geschulte Pflegepersonen gewährleistet wird. Ausschlaggebend ist, dass sowohl ein zeit- als auch ein technikintensiver Aufwand besteht. Bei einer maschinellen invasiven Beatmung ist dies mit einmal täglich einzutragen. Die technische Messung von Vitalparametern ist unter F 4.5.6 zu berück sichtigen, auch wenn diese rund um die Uhr erfolgt." },
  "4.5.13": { definition: "Besuche bei niedergelassenen Ärztinnen und Ärzten zu diagnostischen oder therapeutischen Zwecken Hierunter fallen regelmäßige Besuche bei der niedergelassenen Hausärztin oder beim niedergelassenen Hausarzt oder Fachärztin oder Facharzt zu diagnosti schen oder therapeutischen Zwecken. Wenn eine Unterstützung auf dem Weg zu oder bei Arztbesuchen erforderlich ist, ist diese in durchschnittlicher Häufigkeit zu erfassen. Unterstützung beim Hausbesuch der Ärztin oder des Arztes im Wohnumfeld ist nicht zu berücksichtigen." },
  "4.5.14": { definition: "(bis zu drei Stunden) Besuche von Therapeutinnen oder Therapeuten, medizinischer oder anderer Einrichtungen des Gesundheitswesens (bis zu drei Stunden) Hier ist das Aufsuchen anderer Therapeutinnen oder Therapeuten, zum Beispiel für Physiotherapie/Krankengymnastik, Ergotherapie, Logopädie, Psychothera pie, von Krankenhäusern zur ambulanten Behandlung oder Diagnostik oder anderer Einrichtungen des Gesundheitswesens zu berücksichtigen. Sollte der Gesamtzeitaufwand bei der Nutzung dieser Einrichtungen einschließlich der Fahrtzeiten für die Pflegeperson mehr als drei Stunden umfassen, so ist dies unter Ziffer F 4.5.15 zu berücksichtigen." },
  "4.5.15": { definition: "(länger als drei Stunden) Besuche von Therapeutinnen oder Therapeuten, medizinischer oder anderer Einrichtungen des Gesundheitswesens (länger als drei Stunden) Bei manchen Erkrankungen kann es notwendig sein, spezialisierte Einrichtungen aufzusuchen, wodurch erhebliche Fahrtzeiten anfallen können. Auch kann es erforderlich sein, sich zeitaufwendiger diagnostischer oder therapeutischer Maßnahmen zu unterziehen, zum Beispiel onkologische Behandlung oder Dia lyse. Der dafür erforderliche Zeitaufwand für die Pflegeperson muss pro Termin mehr als drei Stunden betragen. Sollte der Zeitaufwand bei der Nutzung dieser Einrichtungen (einschließlich Fahrtzeiten) unter drei Stunden liegen, so ist dies unter Ziffer F 4.5.13 oder F 4.5.14 zu berücksichtigen." },
  "4.6.1": { definition: "Den Tagesablauf nach individuellen Gewohnheiten und Vorlieben einteilen und bewusst gestalten und gegebenenfalls die Planung an Veränderungen anpassen Grundsätzlich geht es in diesem Kriterium um die planerische Fähigkeit und nicht um die praktische Umsetzung dieser geplanten Aktivitäten. Zu beurteilen ist, ob die Person von sich aus festlegen kann, ob und welche Aktivitäten sie im Laufe des Tages durchführen möchte, zum Beispiel wann sie baden, essen oder zu Bett gehen oder wann sie Fernsehen oder spazieren gehen möchte. Solche Festlegungen setzen voraus, dass die zeitliche Orientierung zumindest teilweise erhalten ist. Die Gutachterin oder der Gutachter kann dies prüfen, indem er sich zum Beispiel den bisherigen oder künftigen Tagesablauf schildern lässt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Routineabläufe können weitgehend selbständig gestaltet werden, bei ungewohnten Veränderungen ist Unterstützung notwendig. Es reichen zum Beispiel Erinnerungshilfen an einzelne für den Tag vereinbarte Termine. Abweichend davon ist als überwiegend selbständig auch eine Person zu bewerten, die zwar selbständig planen und entscheiden kann, deren Kommunikationsfähigkeit oder Sinneswahrnehmung aber beeinträchtigt ist, so dass sie Hilfe benötigt, um den geplanten Tagesablauf mit anderen Menschen abzustimmen.", "Die Person benötigt Hilfe beim Planen des Routinetagesablaufs. Sie ist aber in der Lage, Zustimmung oder Ablehnung zu Strukturierungsangeboten zu signalisieren. Sie kann eigene Planungen häufig nicht einhalten, da diese wieder vergessen werden. Deshalb ist über den ganzen Tag hinweg eine Erinnerung beziehungsweise Aufforderung erforderlich. Abweichend davon ist als überwiegend unselbständig auch eine Person zu bewerten, die zwar selbst planen und entscheiden kann, die aber so stark beeinträchtigt ist, dass sie für jegliche Umsetzung der selbst geplanten Aktivitäten personelle Hilfe benötigt. Betroffen sein können vor allem Personen mit entsprechenden Beeinträchtigungen der Selbständigkeit in den Modulen 1 und 4.", "Mitwirkung an der Planung der Tagesstruktur oder Orientierung an vorgegebenen Strukturen ist nicht oder nur minimal möglich."] },
  "4.6.2": { definition: "Nach individuellen Gewohnheiten einen Tag-Nacht-Rhythmus einhalten und für ausreichende Ruhe- und Schlafphasen sorgen Dazu gehören die Fähigkeit, die Notwendigkeit von Ruhephasen zu erkennen, sich auszuruhen und mit Phasen der Schlaflosigkeit umzugehen aber auch somatische Funktionen, um ins Bett zu kommen und die Ruhephasen insbesondere nachts einhalten zu können. Nächtliche Maßnahmen, die die Bewältigung von und den selbständigen Umgang mit krankheits- oder therapiebedingten Anfor derungen und Belastungen betreffen, werden nicht in diesem Kriterium bewertet, da sie nicht der Sorge für eine ausreichende Ruhe- und Schlafphase dienen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person benötigt personelle Hilfe beim Aufstehen oder Zu-Bett-Gehen, zum Beispiel Transferhilfen oder zeitliche Orientierungshilfen beim Wecken oder Aufforderung, schlafen zu gehen. Oder in der Regel wöchentlich, aber nicht täglich entsteht nachts ein Hilfebedarf.", "Es treten regelmäßig (nahezu jede Nacht) Einschlafprobleme oder nächtliche Unruhe auf, die die Person größtenteils nicht allein bewältigen kann. Deshalb sind aufwendige Einschlafrituale oder beruhigende Ansprache in der Nacht erforderlich. Überwiegend unselbständig ist auch eine Person, die nahezu in jeder Nacht personeller Hilfe bedarf, um weiterschlafen zu können, zum Beispiel bei Lage wechsel oder Toilettengängen in der Nacht.", "Die Person verfügt über keinen oder einen gestörten Schlaf-Wach-Rhythmus. Dies gilt unter anderem für mobile gerontopsychiatrisch erkrankte Personen und auch für Menschen, die keinerlei Aktivitäten ausüben, zum Beispiel im Wach koma, oder Personen, die regelmäßig mindestens dreimal in der Nacht perso nelle Unterstützung benötigen."] },
  "4.6.3": { definition: "Die verfügbare Zeit nutzen, um Aktivitäten durchzuführen, die den eigenen Vorlieben und Interessen entsprechen „Verfügbare Zeit“ ist in diesem Zusammenhang definiert als Zeit, die nicht durch Notwendigkeiten wie Ruhen, Schlafen, Essen, Mahlzeitenzubereitung, Körper pflege, Arbeit et cetera gebunden ist („freie“ Zeit). Bei der Beurteilung geht es vorrangig um die Fähigkeit, nach individuellen kognitiven, manuellen, visuellen oder auditiven Fähigkeiten und Bedürfnissen geeignete Aktivitäten der Freizeitbeschäftigung auszuwählen und auch praktisch durchzuführen, zum Beispiel Handarbeiten, Bücher oder Zeitschriften lesen, Unterhaltungselektronik und Mobilgeräte nutzen. Dies gilt auch für Personen, die Angebote auswählen und steuern können, aber aufgrund somatischer Ein schränkungen für die praktische Durchführung personelle Unterstützung benötigen. Bei der Beurteilung wird von der Annahme ausgegangen, dass die in den Räumlichkeiten befindlichen Gegenstände so in der unmittelbaren Umgebung der Person platziert sind, dass die Person grundsätzlich an alle notwendigen Utensilien herankommt und diese nicht jedes Mal angereicht werden müssen. Beispielsweise ist einer bettlägerigen Person, die entsprechend ihrer Fähigkeiten beziehungsweise Beeinträchtigungen in der Lage ist zu greifen und einen Fernseher mittels einer Fernbedienung zu bedienen, die Fernbedienung so zu positionieren, dass sie danach greifen und den Fernseher bedienen kann.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Es ist nur in geringem Maße Hilfe erforderlich, zum Beispiel Vorbereiten, unmittelbares Zurechtlegen und Richten von Gegenständen, zum Beispiel Utensilien wie Tageszeitung, Kopfhörer oder Ähnliches oder Erinnerung an gewohnte Aktivitäten, Motivation oder Unterstützung bei der Entscheidungsfindung (Vor schläge unterbreiten).", "Die Person kann sich an Beschäftigungen beteiligen, aber nur mit umfassender Anleitung, Begleitung oder motorischer Unterstützung.", "Die Person kann an der Entscheidung oder Durchführung nicht nennenswert mitwirken. Sie zeigt keine Eigeninitiative, kann Anleitungen und Aufforderungen nicht kognitiv umsetzen, beteiligt sich nicht oder nur minimal an angebotenen Beschäftigungen."] },
  "4.6.4": { definition: "Längere Zeitabschnitte überschauend über den Tag hinausplanen Dies kann beispielsweise anhand der Frage beurteilt werden, ob Vorstellungen oder Wünsche zu anstehenden Festlichkeiten wie Geburtstag oder Jahresfeste bestehen, ob die Zeitabläufe eingeschätzt werden können, zum Beispiel vorgegebene Strukturen wie regelmäßige Termine nachvollzogen werden können, oder ob die körperlichen Fähigkeiten vorhanden sind, um eigene Zukunftsplanungen mit anderen Menschen kommunizieren zu können. Es ist auch zu berücksichtigen, wenn stark ausgeprägte psychische Problemlagen (zum Beispiel Ängste) es verhindern, sich mit Fragen des zukünftigen Handelns auseinanderzusetzen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person nimmt sich etwas vor, muss aber erinnert werden, dies auch durchzuführen. Als überwiegend selbständig ist auch eine Person zu bewerten, die zwar selbständig planen und entscheiden kann, deren Kommunikationsfähigkeit oder Sinneswahrnehmung beeinträchtigt ist, so dass sie Hilfe benötigt, um den geplanten Ablauf mit den Personen des näheren Umfelds abzustimmen.", "Die Person plant von sich aus nicht, entscheidet aber mit Unterstützung durch andere Personen. Sie muss an die Umsetzung der eigenen Entscheidungen erinnert werden oder benötigt bei der Umsetzung emotionale oder körperliche Unterstützung. Abweichend davon ist als überwiegend unselbständig auch eine Person zu bewerten, die zwar selbst planen und entscheiden kann, die aber so stark beeinträchtigt ist, dass sie für jegliche Umsetzung der selbst geplanten Aktivitäten personelle Hilfe benötigt. Betroffen sein können vor allem Personen mit entsprechenden Beeinträchtigungen der Selbständigkeit in den Modulen 1 und 4.", "Die Person verfügt nicht über Zeitvorstellungen für Planungen über den Tag hinaus, auch bei Vorgabe von Auswahloptionen wird weder Zustimmung noch Ablehnung signalisiert."] },
  "4.6.5": { definition: "Im direkten Kontakt mit Angehörigen, Pflegepersonen, Mitbewohnern oder Besuchern umgehen, Kontakt aufnehmen, Personen ansprechen, auf Ansprache reagieren", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Im direkten Kontakt mit vertrauten Personen erfolgt die Interaktion selbständig. Bei Interaktion mit nicht vertrauten Personen ist Unterstützung erforderlich, zum Beispiel an der Haustür. Auch eine punktuelle Unterstützung bei der Überwindung von Sprech-, Sprach- oder Hörproblemen ist hier zu werten.", "Die Person ergreift von sich aus kaum Initiative. Sie muss angesprochen oder aufwendig motiviert werden, reagiert dann aber verbal oder deutlich erkennbar durch andere Formen der Kommunikation (Blickkontakt, Mimik, Gestik). Über wiegend unselbständig ist auch eine Person, die auf umfassende Unterstützung bei der Überwindung von Sprech-, Sprach- oder Hörproblemen angewiesen ist.", "Die Person reagiert nicht auf Ansprache. Auch nonverbale Kontaktversuche, zum Beispiel Berührungen, führen zu keiner nennenswerten Reaktion."] },
  "4.6.6": { definition: "Bestehende Kontakte zu Freunden, Bekannten, Nachbarn aufrechterhalten, beenden oder zeitweise ablehnen Dazu gehört auch die Fähigkeit, mit technischen Kommunikationsmitteln wie Telefon umgehen zu können, zum Beispiel Besuche verabreden oder Telefonoder Brief- oder E-Mail-Kontakte.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann planen, braucht aber Hilfe beim Umsetzen wie zum Beispiel Erinnerungszettel bereitlegen oder Telefonnummern mit Namen oder mit Bild versehen, Erinnern und Nachfragen, ob Kontakt hergestellt wurde, oder Erinnern an Terminabsprachen. Pflegeperson wählt die Telefonnummer, die Person führt dann das Gespräch; oder die Person beauftragt die Pflegeperson, ein Treffen mit Freunden, Bekannten zu verabreden.", "Die Kontaktgestaltung der Person ist reaktiv. Sie sucht von sich aus kaum Kontakt, wirkt aber mit, wenn beispielsweise die Pflegeperson die Initiative ergreift. Überwiegend unselbständig ist auch, wer aufgrund von somatischen Beeinträchtigungen während der Kontaktaufnahme personelle Unterstützung durch die Bezugsperson, zum Beispiel bei der Nutzung von Kommunikationshilfen (Telefon halten) oder bei der Überwindung von Sprech-, Sprach- oder Hörproblemen, benötigt.", "Die Person nimmt keinen Kontakt außerhalb des direkten Umfeldes auf und reagiert nicht auf Anregungen zur Kontaktaufnahme."] },
};

export const BESONDERE_BEDARFSKONSTELLATION_EXPLANATION =
  "Gemäß § 15 Absatz 4 SGB XI können Pflegebedürftige mit besonderen Bedarfskonstellationen, die einen spezifischen, außergewöhnlich hohen Hilfebedarf mit besonderen Anforderungen an die pflegerische Versorgung aufweisen, aus pflegefachlichen Gründen dem Pflegegrad 5 zugeordnet werden, auch wenn ihre Gesamtpunkte unter 90 liegen. In Betracht kommen Pflegebedürftige, die rein nach Punkten den Pflegegrad 5 nicht erreichen würden, dieser aber aufgrund der Schwere der Beeinträchtigung angemessen wäre. Als besondere Bedarfskonstellation ist nur die Gebrauchsunfähigkeit beider Arme und beider Beine festgelegt. Hintergrund ist, dass die jeweiligen gesundheitlichen Probleme sich einer pflegefachlichen Systematisierung im neuen Begutachtungsinstrument entziehen. Trotz vollständiger Abhängigkeit von personeller Hilfe ist es möglich, dass bei diesem Personenkreis im Bereich der Module 2 und 3 keine und im Bereich des Moduls 6 Beeinträchtigungen nur im geringen Maß vorliegen, so dass die Gesamtpunkte unter 90 liegen. Gebrauchsunfähigkeit beider Arme und beider Beine mit vollständigem Verlust der Greif-, Steh- und Gehfunktionen, die nicht durch Einsatz von Hilfsmitteln kompensiert werden Das Kriterium erfasst in der Regel Personen mit einer Bewegungsunfähigkeit beider Arme und beider Beine unabhängig von der Ursache. Gebrauchsunfähigkeit beider Arme und beider Beine mit vollständigem Verlust der Greif-, Steh- und Gehfunktionen liegt zum Beispiel vor bei kompletten Lähmungen aller Extremitäten oder bei Menschen im Wachkoma. Auch bei hochgradigen Kontrakturen, Versteifungen, bei hochgradigem Tremor, Rigor oder Athetose kann die besondere Bedarfskonstellation vorliegen. Eine Gebrauchsunfähigkeit beider Arme und beider Beine liegt auch vor, wenn eine minimale Restbeweglichkeit der Arme vorhanden ist oder nur noch unkontrollierbare Greifreflexe bestehen.";
